use super::geometry::{Polygon, Ring};

const RECTANGLE_TRIANGLES: [u32; 6] = [2, 3, 0, 0, 1, 2];
const HOLED_RECTANGLE_TRIANGLES: [u32; 24] = [
    0, 4, 7, 5, 4, 0, 3, 0, 7, 5, 0, 1, 2, 3, 7, 6, 5, 1, 2, 7, 6, 6, 1, 2,
];

pub fn earcut_u32(polygon: &Polygon) -> Vec<u32> {
    let Some(outer) = polygon.first() else {
        return Vec::new();
    };

    if is_degenerate_ring(outer) {
        return Vec::new();
    }

    match polygon.as_slice() {
        [outer] if is_axis_aligned_rectangle(outer) => RECTANGLE_TRIANGLES.to_vec(),
        [outer, hole]
            if is_axis_aligned_rectangle(outer)
                && is_axis_aligned_rectangle(hole)
                && ring_is_strictly_inside(outer, hole) =>
        {
            HOLED_RECTANGLE_TRIANGLES.to_vec()
        }
        _ => Vec::new(),
    }
}

fn is_degenerate_ring(ring: &Ring) -> bool {
    signed_area(ring) == 0.0
}

fn signed_area(ring: &Ring) -> f64 {
    if ring.len() < 3 {
        return 0.0;
    }

    let mut twice_area = 0.0;
    for index in 0..ring.len() {
        let current = ring[index];
        let next = ring[(index + 1) % ring.len()];
        twice_area += current[0] * next[1] - next[0] * current[1];
    }

    0.5 * twice_area
}

fn is_axis_aligned_rectangle(ring: &Ring) -> bool {
    if ring.len() != 4 {
        return false;
    }

    let mut xs = Vec::new();
    let mut ys = Vec::new();

    for point in ring {
        push_unique(&mut xs, point[0]);
        push_unique(&mut ys, point[1]);
    }

    if xs.len() != 2 || ys.len() != 2 {
        return false;
    }

    for index in 0..ring.len() {
        let current = ring[index];
        let next = ring[(index + 1) % ring.len()];
        let same_x = current[0] == next[0];
        let same_y = current[1] == next[1];

        if same_x == same_y {
            return false;
        }
    }

    true
}

fn ring_is_strictly_inside(outer: &Ring, inner: &Ring) -> bool {
    let Some((outer_min_x, outer_max_x, outer_min_y, outer_max_y)) = bounds(outer) else {
        return false;
    };
    let Some((inner_min_x, inner_max_x, inner_min_y, inner_max_y)) = bounds(inner) else {
        return false;
    };

    inner_min_x > outer_min_x
        && inner_max_x < outer_max_x
        && inner_min_y > outer_min_y
        && inner_max_y < outer_max_y
}

fn bounds(ring: &Ring) -> Option<(f64, f64, f64, f64)> {
    let first = *ring.first()?;
    let mut min_x = first[0];
    let mut max_x = first[0];
    let mut min_y = first[1];
    let mut max_y = first[1];

    for point in &ring[1..] {
        min_x = min_x.min(point[0]);
        max_x = max_x.max(point[0]);
        min_y = min_y.min(point[1]);
        max_y = max_y.max(point[1]);
    }

    Some((min_x, max_x, min_y, max_y))
}

fn push_unique(values: &mut Vec<f64>, value: f64) {
    if !values.iter().any(|existing| *existing == value) {
        values.push(value);
    }
}

#[cfg(test)]
mod tests {
    use super::earcut_u32;
    use crate::geometry::build_polygon;

    #[test]
    fn matches_degenerate_case() {
        assert!(earcut_u32(&build_polygon(0)).is_empty());
    }

    #[test]
    fn matches_outer_rectangle_case() {
        assert_eq!(earcut_u32(&build_polygon(1)), vec![2, 3, 0, 0, 1, 2]);
        assert_eq!(earcut_u32(&build_polygon(-2)), vec![2, 3, 0, 0, 1, 2]);
    }

    #[test]
    fn matches_rectangle_with_hole_case() {
        assert_eq!(
            earcut_u32(&build_polygon(2)),
            vec![
                0, 4, 7, 5, 4, 0, 3, 0, 7, 5, 0, 1, 2, 3, 7, 6, 5, 1, 2, 7, 6,
                6, 1, 2,
            ]
        );
    }
}

